/**
 * get_type_definition tool — lookup a GraphQL type by name.
 */
import { z } from 'zod';
export const getTypeDefinitionSchema = z.object({
    type_name: z.string().max(200).describe('Name of a GraphQL type, enum, scalar, input, or interface (e.g. "Token", "AddressFilter", "OrderDirection")'),
});
function levenshtein(a, b) {
    const m = a.length, n = b.length;
    const dp = Array.from({ length: m + 1 }, () => Array(n + 1).fill(0));
    for (let i = 0; i <= m; i++)
        dp[i][0] = i;
    for (let j = 0; j <= n; j++)
        dp[0][j] = j;
    for (let i = 1; i <= m; i++) {
        for (let j = 1; j <= n; j++) {
            dp[i][j] = a[i - 1] === b[j - 1]
                ? dp[i - 1][j - 1]
                : 1 + Math.min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1]);
        }
    }
    return dp[m][n];
}
export function handleGetTypeDefinition(input, schema) {
    if (!schema) {
        return 'Schema data not available. Data files may be missing — try reinstalling the package.';
    }
    const name = input.type_name.trim();
    const nameLower = name.toLowerCase();
    // Search across all type categories
    const obj = schema.objectTypes.find(t => t.name.toLowerCase() === nameLower);
    if (obj) {
        const fields = obj.fields.map(f => `  - \`${f.name}\`: \`${f.type}\`${f.required ? ' (non-null)' : ''}${f.description ? ` — ${f.description}` : ''}`).join('\n');
        const impl = obj.implements?.length ? `\n**Implements:** ${obj.implements.join(', ')}` : '';
        return `# ${obj.name} (object type)\n\n${obj.description || ''}${impl}\n\n**Fields:**\n${fields}`;
    }
    const inp = schema.inputTypes.find(t => t.name.toLowerCase() === nameLower);
    if (inp) {
        const fields = inp.fields.map(f => `  - \`${f.name}\`: \`${f.type}\`${f.required ? ' (required)' : ''}${f.description ? ` — ${f.description}` : ''}`).join('\n');
        return `# ${inp.name} (input type)\n\n${inp.description || ''}\n\n**Fields:**\n${fields}`;
    }
    const enm = schema.enums.find(t => t.name.toLowerCase() === nameLower);
    if (enm) {
        const vals = enm.values.map(v => `  - \`${v.name}\`${v.description ? ` — ${v.description}` : ''}`).join('\n');
        return `# ${enm.name} (enum)\n\n${enm.description || ''}\n\n**Values:**\n${vals}`;
    }
    const scalar = schema.scalars.find(t => t.name.toLowerCase() === nameLower);
    if (scalar) {
        return `# ${scalar.name} (scalar)\n\n${scalar.description}`;
    }
    const iface = schema.interfaces.find(t => t.name.toLowerCase() === nameLower);
    if (iface) {
        const fields = iface.fields.map(f => `  - \`${f.name}\`: \`${f.type}\`${f.required ? ' (non-null)' : ''}${f.description ? ` — ${f.description}` : ''}`).join('\n');
        return `# ${iface.name} (interface)\n\n${iface.description || ''}\n\n**Fields:**\n${fields}`;
    }
    // Not found — suggest closest matches
    const allNames = [
        ...schema.objectTypes.map(t => t.name),
        ...schema.inputTypes.map(t => t.name),
        ...schema.enums.map(t => t.name),
        ...schema.scalars.map(t => t.name),
        ...schema.interfaces.map(t => t.name),
    ];
    const suggestions = allNames
        .map(n => ({ name: n, dist: levenshtein(nameLower, n.toLowerCase()) }))
        .sort((a, b) => a.dist - b.dist)
        .slice(0, 5)
        .map(s => s.name);
    return `Type "${name}" not found. Did you mean: ${suggestions.join(', ')}?`;
}
